// Helper function to split a string into substrings based on start and end indices.
List<String> _splitIntoSubstrings(String s, List<int> indices) {
  final List<String> result = [];
  int prevIndex = 0;

  for (final int index in indices) {
    if (index > prevIndex) {
      result.add(s.substring(prevIndex, index));
    }
    prevIndex = index;
  }

  // Add the last substring if there's any remaining characters
  if (prevIndex < s.length) {
    result.add(s.substring(prevIndex));
  }

  return result;
}
