    if (i < musicString.length && (musicString[i] == '#' || musicString[i] == '&')) {
      hasSharpOrFlat = true;
      ++i;
    } else {
      // If no sharp/flat symbol found and the current note was just one character,
      // then we need to check if there are more characters following as part of the same note. 
      // This could be due to multi-character note names like "C#" which would have been parsed as 'C' followed by a '#' etc.

      // For this example, assume that each note is single character with possible # or & after.
      // So in case of single character, move on.
      if (noteStr.length > 1) {
        throw FormatException('Invalid note name');
      }
    }

    int index = -1;
    try {
      index = notes.indexOf(noteStr);
    } catch (e) {
      throw FormatException('Unknown note $noteStr at position ${i}');
    }

    if (index == -1) {
      throw FormatException('Unknown note $noteStr at position ${i}');
    }

    int octave = 4; // default octave

    // Check for optional octave value
    if (hasSharpOrFlat) {
      if (i >= musicString.length) {
        throw FormatException("Missing number after sharp or flat");
      }
      int octNum = int.tryParse(musicString[i]);
      if (octNum == null) {
