  if (substring.isEmpty || substring.length > string.length) return 0;

  int count = 0;
  final subLen = substring.length;
  for (int i = 0; i <= string.length - subLen; i++) {
    if (string.substring(i, i + subLen) == substring) {
      count++;
    }
  }
  return count;
