int fruitDistribution(String s, int n) {
  if (s.isEmpty || n == 0) return 0;

  final List<int> counts = [];
  for (var i = 0; i < s.length; i++) {
    var c = s[i];
    // Check if the character is a letter (a-z or A-Z)
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
      var count = 0;
      for (var j = i + 1; j < s.length; j++) {
        if (s[j] == c) {
          count++;
        }
      }
      counts.add(count);
      i += count;
    } else {
      // If it's not a letter, skip and check next character
      continue;
    }
  }

  if (counts.isEmpty) return 0;

  int totalFruits = counts.reduce((sum, e) => sum + e);

  // Calculate how many full baskets can be filled with all fruits
  int basketSize = 5 * (n - 1); 
  int maxBaskets = totalFruits ~/ basketSize;

  int remainingFruitsAfterFullBaskets = totalFruits % basketSize;

  // Distribute remaining fruits as evenly as possible across the baskets
  int extraPerBasket = remainingFruitsAfterFullBaskets % n;
  int baseExtra = remainingFruitsAfterFullBaskets ~/ n;

  int totalDistributed = maxBaskets * basketSize;

  // Add the base extras to each basket first
  totalDistributed += baseExtra * n;

  // Then distribute the remainder among some baskets
  totalDistributed += extraPerBasket;

  return totalDistributed;
}
