String antiShuffle(String s) {
  if (s.isEmpty) return '';

  final List<String> words = [];
  int i = 0;
  while (i < s.length) {
    if (s[i] == ' ') {
      i++;
      continue;
    }

    var j = i + 1;
    while (j < s.length && s[j] != ' ') {
      j++;
    }

    words.add(s.substring(i, j));
    i = j;
