  // Initialize a DP table where dp[i][j] represents the maximum number of filled units
  // up to row i and column j with j units of capacity used.
  List<List<int>> dp = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j <= cols; ++j) {
      // If we don't take this cell's value
      dp[i+1][j] = dp[i][j];

      // Try taking this cell's value, but only if possible
      if (j >= grid[i][j]) {
        dp[i+1][j] = max(dp[i+1][j], dp[i][j - grid[i][j]] + grid[i][j]);
      }
    }
  }

  return dp[rows][capacity];
}

