        dfs(nx, ny, currentCapacity, visited, path);
      }
    }

    // If we cannot extend further and it's not an end of the row/column
    if (!canExtend) {
      result = max(result, currentCapacity);
    } else if (path.length == 1) {
      // Only possible when starting from the first node
      result = max(result, currentCapacity);
