import 'dart:collection';

bool isSorted(List<int> lst) {
  if (lst.length <= 1) return true;

  final queue = Queue<int>();
  for (int i in lst) {
    queue.add(i);
  }

  int prev = queue.removeFirst();
  while (!queue.isEmpty) {
    int curr = queue.removeFirst();
    if (curr < prev) return false;
    prev = curr;
  }

  return true;
}

