List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Directions: right and down
  List<List<int>> directions = [[0,1], [1,0]];

  // Priority queue to store (sum, row, col)
  PriorityQueue pq = PriorityQueue<QueueItem>((a, b) => a.sum.compareTo(b.sum));

  // Visited matrix with the minimum sum at each cell
  var visited = List.generate(rows, (_) => List.filled(cols, null));

  void addNeighbors(int r, int c, int currentSum) {
    for (var dir in directions) {
      int nr = r + dir[0];
      int nc = c + dir[1];

      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
          visited[nr][nc] == null) {
        int newSum = currentSum + grid[nr][nc];

        // If we haven't visited this cell or found a smaller path
        if (visited[nr][nc] == null || newSum < visited[nr][nc]) {
          visited[nr][nc] = newSum;
          pq.add(QueueItem(newSum, nr, nc));
        }
      }
    }
  }

  // Start from top-left corner
  pq.add(QueueItem(grid[0][0], 0, 0));
  visited[0][0] = grid[0][0];

  while (!pq.isEmpty) {
    QueueItem item = pq.removeFirst();

    int currRow = item.row;
    int currCol = item.col;
    int currSum = item.sum;

    // Check if reached bottom-right
    if (currRow == rows - 1 && currCol == cols - 1) {
      return [item.sum]; 
    }

    addNeighbors(currRow, currCol, currSum);
  }

  throw Exception('No valid path found');
}

class QueueItem implements Comparable<QueueItem> {
  final int sum;
  final int row;
  final int col;

  QueueItem(this.sum, this.row, this.col);

  @override
  int compareTo(other) {
    return sum.compareTo(other.sum);
  }
}

