  final rows = grid.length;
  final cols = grid[0].length;

  // Directions: right and down
  const directions = <int>[1, 0]; // [dx, dy]

  var dp = List.generate(rows * cols + 2, (_) => -1);
  var visited = List<bool>.filled(rows * cols, false);

  void dfs(int x, int y, int steps, int sum) {
    if (x >= rows || y >= cols) return; // out of bounds
    if (steps > k) return; // exceeded max steps
    if (visited[x * cols + y]) return; // prevent revisiting the same cell

    final idx = x * cols + y;
    final currentVal = grid[x][y];

    if (sum == -1) {
      // Initial call for first step
      dp[idx] = steps;
    } else {
      dp[idx] = min(dp[idx], steps);
    }

    visited[idx] = true;

    for (final dir in directions) {
      final nx = x + dir;
      final ny = y;
      if (nx >= 0 && ny >= 0 && nx < rows && ny < cols) {
        dfs(nx, ny, steps + 1, sum + currentVal);
      }
    }

    visited[idx] = false;
  }

  dfs(0, 0, 0, 0);

  // Now find the minimum number of steps needed to reach a path with exactly 'k' elements
  var result = -1;
  for (var i = 0; i < rows * cols; ++i) {
    if (dp[i] != -1 && dp[i] <= k) {
      result = min(result, dp[i]);
    }
  }

  return [result];
}

