    if (current.yp > 0) neighbors.add(1); 
    if (current.xp < cols-1) neighbors.add(2);
    if (current.yp < rows-1) neighbors.add(3);
    if (current.xp > 0) neighbors.add(4);

    for (var direction in neighbors) {
      int newX = current.xp;
      int newY = current.yp;

      switch(direction) {
        case 1:
