class tuple3<T1, T2, T3> implements Comparable<tuple3<T1, T2, T3>> {
  final T1 item1;
  final T2 item2;
  final T3 item3;

  const tuple3(this.item1, this.item2, this.item3);

  @override
  int compareTo(tuple3 other) {
    if (item1 is num && other.item1 is num) {
      return (item1 as num).compareTo(other.item1 as num);
    } else if (item1 is String && other.item1 is String) {
      return (item1 as String).compareTo(other.item1 as String);
    }
    throw UnsupportedError('Comparison not supported');
  }
}

