  List<int> dp = List.filled(rows * cols + 1, -1);

  void dfs(int r, int c, int sum) {
    if (r < 0 || r >= rows || c < 0 || c >= cols || sum > k) return;

    var index = r * cols + c;

    // Base case: reached end of the grid
    if (index == rows * cols - 1) {
      dp[index] = max(dp[index], sum); 
      return;
