    // Check if we can update the current position's minimum sum
    if (dp[index] == -1 || sum < dp[index]) {
      dp[index] = sum;
    }
  }

  dfs(0, 0, grid[0][0]);

  return dp; // Return the list containing the minimal sums at each cell
}

