String fixSpaces(String text) {
  final List<String> lines = text.split('\n');
  for (int i = 0; i < lines.length; i++) {
    String line = lines[i];
    // Split the line into words and spaces, keeping track of original spacing
    List<String> tokens = [];
    int index = 0;

    while (index < line.length) {
      if (line[index] == ' ') {
        tokens.add(' ');
        index++;
      } else {
        int start = index;
        while (index < line.length && line[index] != ' ') {
          index++;
        }
        tokens.add(line.substring(start, index));
      }
    }

    // Rebuild the line by replacing each space with a single space,
    // but preserve leading/trailing whitespace as per original
    bool hasLeadingSpace = false;
    bool hasTrailingSpace = false;

    // Check for leading spaces
    while (tokens.isNotEmpty && tokens[0] == ' ') {
      tokens.removeAt(0);
      hasLeadingSpace = true;
    }

    // Check for trailing spaces
    while (tokens.isNotEmpty && tokens.last == ' ') {
      tokens.removeLast();
      hasTrailingSpace = true;
    }

    // Replace multiple spaces between words with one space
    List<String> newTokens = [];
    String currentWordOrSpace = '';

    for (var token in tokens) {
      if (token == ' ') {
        if (currentWordOrSpace.isEmpty || currentWordOrSpace == ' ') {
          currentWordOrSpace += token;
        }
      } else {
        if (!currentWordOrSpace.isEmpty) {
          newTokens.add(currentWordOrSpace);
          currentWordOrSpace = '';
        }
        newTokens.add(token);
      }
    }

    if (currentWordOrSpace.isNotEmpty) {
      newTokens.add(currentWordOrSpace);
    }

    // Now handle leading and trailing spaces
    if (hasLeadingSpace) {
      newTokens.insert(0, ' ');
    }
    if (hasTrailingSpace) {
      newTokens.add(' ');
    }

    // Join the tokens to form the fixed line
    String fixedLine = newTokens.join('');
    lines[i] = fixedLine;
  }

  return lines.join('\n');
}
