String findMax(List<String> words) {
  if (words.isEmpty) return '';

  var maxWord = words[0];
  for (int i = 1; i < words.length; i++) {
    String current = words[i];
    int lengthDiff = current.length - maxWord.length;

    if (lengthDiff > 0 || 
        (lengthDiff == 0 && _isPalindrome(current) && !_isPalindrome(maxWord))) {
      maxWord = current;
    }
  }

  return maxWord;
}

bool _isPalindrome(String s) {
  final List<String> chars = s.split('');
  int left = 0, right = chars.length - 1;

  while (left < right) {
    if (chars[left] != chars[right]) return false;
    left++;
    right--;
  }

  return true;
}
